    var p: [int] = [0, 1, 1]
    var i = 3
    while i <= n:
        prev = p[i - 1]
        p.append(p[prev] + p[i - prev])
    i += 1
    return p[n]


fn build_combinations(l: [str], n: int, start: int, inout current: [str], inout result: [[str]]):
    if len(current) == n:
        result.append(current)
        return
    for i in range(start, len(l)):
        current.append(l[i])
        build_combinations(l, n, i, &current, &result)
        current.pop()

fn combinations_colors(l: [str], n: int) -> [[str]]:
    """
    Write a function that takes in a list and length n, and generates all combinations (with repetition) of the elements of the list and returns a list with a list for each combination.
    """
    var result: [[str]] = []
    var current: [str] = []
    build_combinations(l, n, 0, &current, &result)
    return result


fn unique(l: [int]) -> [int]:
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    seen: {int} = set(l)
    return sorted(seen)


fn select_words(s: str, n: int) -> [str]:
    """Return words of s with exactly n consonants, in order."""
    var result: [str] = []
    for word in s.split(" "):
        if word == "":
            continue
        var count = 0
        for c in word.lower():
            if c.isalpha() and not (c in "aeiou"):
                count += 1
        if count == n:
            result.append(word)
    return result


fn specialFilter(nums: [int]) -> int:
    """Write a function that takes an array of numbers as input and returns 
    the number of elements in the array that are greater than 10 and both 
    first and last digits of a number are odd (1, 3, 5, 7, 9).
    For example:
    >>> specialFilter([15, -73, 14, -15])
    1 
    >>> specialFilter([33, -2, -3, 45, 21, 109])
    2
    """
    var count = 0
    for n in nums:
        if n > 10:
            last = n % 10
            var first = n
            while first >= 10:
                first = first // 10
            if last % 2 == 1 and first % 2 == 1:
                count += 1
    return count


fn check_K(test_tup: [int], K: int) -> bool:
    """
    Write a function to check if the given tuples contain the k or not.
    """
    return test_tup.contains(K)
